'use strict';
function main(){
var seed=23;
var subs=["ballistic","thermal","buoyancy","power","comms"];
var out=[];for(var i=0;i<subs.length;i++){out.push({subsystem:subs[i],status:(seed+i)%7===0?"service":"ready"});}
return {seed:seed, subsystems:out};
}
